mapper.select:
SELECT USER_ID AS userId , USER_NM AS userNm , DEPT_NM AS deptNm , JOB_ROLE AS jobRole , POSITION_NM AS positionNm , CAREER_YEARS AS careerYears , (SELECT FLOOR(IFNULL(SUM(SUB.INPUT_RATE), 0) * 100) FROM TB_PROJECT_ASSIGN SUB WHERE SUB.USER_ID = TB_USER.USER_ID AND SUB.DEL_YN = 'N' AND CURDATE() BETWEEN SUB.START_DATE AND SUB.END_DATE ) AS currentLoad , JOIN_DT AS joinDt , USE_YN AS useYn FROM TB_USER WHERE DEL_YN = 'N'
AND USER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY JOIN_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

