UPDATE TB_USER SET
      USER_NM       = #{userNm}
    , DEPT_NM       = #{deptNm}
    , JOB_ROLE      = #{jobRole}
    , POSITION_NM   = #{positionNm}
    , CAREER_YEARS  = #{careerYears}
    , USE_YN        = #{useYn}
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE USER_ID = #{userId}

UPDATE TB_USER SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE USER_ID = #{userId}
